<?php
require_once __DIR__.'/../includes/permissions.php'; require_role('superadmin'); require_once __DIR__.'/_helpers.php';
$page_title='Denúncias'; $pdo=db();
$labels=['open'=>'Aberta','in_review'=>'Em análise','resolved'=>'Resolvida','dismissed'=>'Dispensada'];
if(is_post()) { verify_csrf($_POST['csrf']??''); $id=safe_int($_POST['id']??0); $status=(string)($_POST['status']??''); $resolution=mb_substr(trim((string)($_POST['resolution']??'')),0,2000); $s=$pdo->prepare('SELECT id,reporter_id,subject,status FROM complaints WHERE id=?'); $s->execute([$id]); $c=$s->fetch(); if(!$c || !in_array($status,['in_review','resolved','dismissed'],true)) { flash('danger','Denúncia ou estado inválido.'); } else { $pdo->prepare('UPDATE complaints SET status=?,resolution=?,reviewed_by=?,reviewed_at=NOW() WHERE id=?')->execute([$status,$resolution!==''?$resolution:null,user()['id'],$id]); if($c['status']!==$status) notify((int)$c['reporter_id'],'Denúncia atualizada','A sua denúncia "'.$c['subject'].'" está agora: '.$labels[$status].'.'.($resolution!==''?' Nota: '.$resolution:'')); audit(user()['id'],'moderate','complaints','Denúncia #'.$id.' marcada como '.$status); flash('success','Denúncia atualizada.'); } redirect(admin_self_url()); }
$status=$_GET['status']??'open'; $allowed=['all','open','in_review','resolved','dismissed']; if(!in_array($status,$allowed,true))$status='open';
$where=''; $params=[]; if($status!=='all'){ $where=' WHERE c.status=?'; $params[]=$status; }
$perPage=20; [$page,$offset]=page_offset($perPage); $cnt=$pdo->prepare('SELECT COUNT(*) FROM complaints c'.$where); $cnt->execute($params); $total=(int)$cnt->fetchColumn();
$sql='SELECT c.*,u.name reporter_name,ru.name reported_name,p.name product_name,o.order_number FROM complaints c JOIN users u ON u.id=c.reporter_id LEFT JOIN users ru ON ru.id=c.reported_user_id LEFT JOIN products p ON p.id=c.product_id LEFT JOIN orders o ON o.id=c.order_id'.$where.' ORDER BY c.created_at DESC, c.id DESC LIMIT '.$perPage.' OFFSET '.$offset; $s=$pdo->prepare($sql);$s->execute($params);$complaints=$s->fetchAll();
include __DIR__.'/../includes/header.php';
?><div class="dashboard-layout"><?php include __DIR__.'/../includes/sidebar.php';?><section class="dashboard-content"><div class="dashboard-top"><div><span class="eyebrow">Moderação</span><h1>Denúncias</h1><p class="text-muted">Analise problemas reportados por compradores e agricultores.</p></div></div><div class="d-flex flex-wrap gap-2 mb-3"><?php foreach(['open'=>'Abertas','in_review'=>'Em análise','resolved'=>'Resolvidas','dismissed'=>'Dispensadas','all'=>'Todas'] as $key=>$label): ?><a class="btn btn-sm <?=$status===$key?'btn-primary':'btn-outline-primary'?>" href="?status=<?=$key?>"><i class="bi bi-filter me-1"></i><?=$label?></a><?php endforeach; ?></div><div class="content-card"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Assunto</th><th>Denunciante</th><th>Referência</th><th>Estado</th><th>Data</th><th>Ação</th></tr></thead><tbody><?php foreach($complaints as $c): ?><tr><td><strong><?=e($c['subject'])?></strong><small class="d-block text-muted"><?=e(mb_strimwidth($c['description'],0,90,'…'))?></small></td><td><?=e($c['reporter_name'])?><?php if($c['reported_name']): ?><small class="d-block text-muted">Visado: <?=e($c['reported_name'])?></small><?php endif; ?></td><td><?php if($c['product_id'] && $c['product_name']): ?><a href="<?=base_path('produto.php?id='.(int)$c['product_id'])?>" target="_blank" rel="noopener"><i class="bi bi-basket2 me-1"></i><?=e($c['product_name'])?></a><?php endif; ?><?php if($c['order_id'] && $c['order_number']): ?><a class="d-block" href="<?=base_path('admin/pedido.php?id='.(int)$c['order_id'])?>"><i class="bi bi-receipt me-1"></i><?=e($c['order_number'])?></a><?php endif; ?><?php if(!$c['product_name'] && !$c['order_number']): ?>—<?php endif; ?></td><td><span class="badge text-bg-<?=$c['status']==='resolved'?'success':($c['status']==='dismissed'?'secondary':($c['status']==='in_review'?'info':'warning'))?>"><i class="bi bi-flag me-1"></i><?=e($labels[$c['status']]??$c['status'])?></span></td><td><?=date('d/m/Y H:i',strtotime($c['created_at']))?></td><td><button type="button" class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#complaint<?=$c['id']?>"><i class="bi bi-eye me-1"></i>Ver</button></td></tr><?php endforeach; if(!$complaints): ?><tr><td colspan="6" class="text-center text-muted py-5"><i class="bi bi-flag display-6 d-block mb-2"></i>Não existem denúncias neste estado.</td></tr><?php endif; ?></tbody></table></div><?=pagination($page,$perPage,$total)?></div><?php foreach($complaints as $c): ?><div class="modal fade" id="complaint<?=$c['id']?>" tabindex="-1" aria-labelledby="complaintTitle<?=$c['id']?>" aria-hidden="true"><div class="modal-dialog"><div class="modal-content"><form method="post"><div class="modal-header"><h5 class="modal-title" id="complaintTitle<?=$c['id']?>"><?=e($c['subject'])?></h5><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Fechar"></button></div><div class="modal-body"><?=csrf_field()?><input type="hidden" name="id" value="<?=$c['id']?>"><p class="small text-muted mb-2">Por <?=e($c['reporter_name'])?> · <?=date('d/m/Y H:i',strtotime($c['created_at']))?> · <?=e($labels[$c['status']]??$c['status'])?></p><p><?=nl2br(e($c['description']))?></p><?php if($c['product_id'] && $c['product_name']): ?><p class="small mb-1"><i class="bi bi-basket2 me-1"></i>Produto: <a href="<?=base_path('produto.php?id='.(int)$c['product_id'])?>" target="_blank" rel="noopener"><?=e($c['product_name'])?></a></p><?php endif; ?><?php if($c['order_id'] && $c['order_number']): ?><p class="small"><i class="bi bi-receipt me-1"></i>Pedido: <a href="<?=base_path('admin/pedido.php?id='.(int)$c['order_id'])?>"><?=e($c['order_number'])?></a></p><?php endif; ?><label class="form-label" for="resolution<?=$c['id']?>">Resolução / nota (enviada ao denunciante)</label><textarea id="resolution<?=$c['id']?>" name="resolution" class="form-control" rows="3" maxlength="2000"><?=e($c['resolution']??'')?></textarea></div><div class="modal-footer"><button name="status" value="in_review" class="btn btn-outline-primary">Em análise</button><button name="status" value="dismissed" class="btn btn-outline-secondary">Dispensar</button><button name="status" value="resolved" class="btn btn-primary">Resolver</button></div></form></div></div></div><?php endforeach; ?></section></div><?php include __DIR__.'/../includes/footer.php'; ?>
